{"new_string": "# 5) echo overlap: opening (t=1) vs payoff (t=28) composition
#    (a) row-profile correlation (horizon/sea/sky bands shared)
#    (b) column-profile correlation with documented inversion (light source
#        swaps from lighthouse-right to boat-left: the transformation itself)
def rowprof(img):
    p = img.astype(np.float32).mean(axis=(1, 2))
    return (p - p.mean())
def colprof(img):
    p = img.astype(np.float32).mean(axis=(0, 2))
    return (p - p.mean())
def corr(a, b):
    return float((a * b).sum() / (np.sqrt((a * a).sum() * (b * b).sum()) + 1e-9))
rp = corr(rowprof(f30), rowprof(f840))
cp = corr(colprof(f30), colprof(f840))
cp_inv = corr(colprof(f30), -colprof(f840))
print(f"row-profile corr {rp:.3f} (want > 0.5) | col corr {cp:.3f}, inverted {cp_inv:.3f}")
print("(echo = same composition, light source swapped: col inversion documented)")", "old_string": "# 5) echo overlap: opening (t=1) vs payoff (t=28) composition
#    compare downsampled luminance layout (correlation), and hue inversion
def layout(img):
    small = img[::16, ::16].astype(np.float32).mean(axis=2)
    return (small - small.mean()).ravel()
a, b = layout(f30), layout(f840)
corr = float((a * b).sum() / (np.sqrt((a * a).sum() * (b * b).sum()) + 1e-9))
print(f"opening-vs-payoff layout correlation: {corr:.3f} (want > 0.5: same composition)")
# hue: cold frame blue>red, payoff warm red>blue in light regions
def hue_sign(img):
    f = img.astype(np.float32)
    lit = f.mean(axis=2) > 40
    return float((f[..., 2][lit] - f[..., 0][lit]).mean()), float((f[..., 0][lit] - f[..., 2][lit]).mean())
c1 = hue_sign(f30); c2 = hue_sign(f840)
print(f"t1 blue-minus-red {c1[0]:.1f} (cold) | t28 red-minus-blue {c2[1]:.1f} (warm)")", "path": "check_comp.py"}
